def solve(graph, start, end):
    if start == end:
        return 0
    seen = {start}
    queue = [start]
    for _ in range(len(queue)):
        node = queue.pop(0)
        for neighbor in graph.get(node, ()):
            if neighbor not in seen:
                seen.add(neighbor)
                queue.append(neighbor)
                if neighbor == end:
                    return len(queue) - 1
    return -1
```

